import { expect, expectStatus, test, type Document } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const vendor = await factory.vendor({ as: "member" });
  // The server compares expiry with its UTC date, so "yesterday" is the UTC date minus one day.
  const yesterday = new Date(Date.now() - 86_400_000).toISOString().slice(0, 10);
  const expiredCertificate = `Insurer: Harbor Mutual\nPolicy Number: HM-55-9001\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`;
  await factory.upload(vendor.id, "w9");
  await factory.upload(vendor.id, "contract");
  const insurance = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: { name: "insurance.txt", mimeType: "text/plain", buffer: Buffer.from(expiredCertificate) },
      },
    }),
    201,
  );
  await expect
    .poll(
      async () =>
        (await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200))
          .map((d) => d.status)
          .sort(),
      { message: "extraction finishes for all three documents", timeout: 30_000 },
    )
    .toEqual(["extracted", "extracted", "extracted"]);
  const submitted = await expectStatus<{ status: string }>(
    await member.post(`/api/vendors/${vendor.id}/submit`),
    200,
  );
  expect(submitted.status).toBe("in_review");
  const extraction = await factory.extraction(insurance.id, "member");
  expect(extraction.status).toBe("pending_review");

  // Act
  const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expired");
  // Re-read the stored state: the refused approval must not have changed the extraction.
  expect((await factory.extraction(insurance.id, "reviewer")).status).toBe("pending_review");
});
